class StorageFixture {
  data = new Map()
  limit = Infinity
  blocked = false
  get length() { return this.data.size }
  key(index) { return [...this.data.keys()][index] ?? null }
  getItem(key) { if (this.blocked) throw new DOMException('Blocked', 'SecurityError'); return this.data.get(key) ?? null }
  removeItem(key) { if (this.blocked) throw new DOMException('Blocked', 'SecurityError'); this.data.delete(key) }
  setItem(key, value) {
    if (this.blocked) throw new DOMException('Blocked', 'SecurityError')
