  assert.equal(signedIn.data.user.id, user.id)
  const reloaded = client(adapter(local, session))
  assert.equal((await reloaded.auth.getSession()).data.session.access_token, accessToken)
  assert.equal((await reloaded.auth.getUser()).data.user.id, user.id)
  assert.equal(local.getItem('cronos.projects'), before)
  assert.equal((await reloaded.auth.signOut()).error, null)
  assert.equal(adapter(local, session).getItem('sb-quota-test-auth-token'), null)
  first.auth.stopAutoRefresh(); reloaded.auth.stopAutoRefresh()
})

import { hydrateLocalCollection, readLocalCollection, saveLocalAndRemoteCollectionStrict } from './remoteRecords'
import type { CustomerQuote, Project, ProjectPurchaseOrder, PurchaseOrderLine, UserProfile } from '../types'
import { calculateQuoteSummary } from './calculations'
import { loadProjects } from './localProjects'

const TASKS_KEY = 'cronos.procurementTasks'
const DUE_OUTS_KEY = 'cronos.procurementDueOuts'
const ACTIVITY_KEY = 'cronos.procurementActivityLog'

export type ProcurementPriority = 'Low' | 'Medium' | 'High' | 'Critical'
export type ProcurementStatus = 'Open' | 'In Progress' | 'Waiting' | 'Complete' | 'Resolved'
export type WaitingOn = 'Vendor' | 'Internal Approval' | 'Customer' | 'Cronos'
export type RelatedRecordType = 'Quote' | 'PO' | 'Vendor' | 'Shipment' | 'RMA' | 'Project'
export type RiskSeverity = 'Low' | 'Medium' | 'High' | 'Critical'
export type ShipmentStatus = 'In transit' | 'Delivering today' | 'Delivered' | 'Delayed' | 'Exception' | 'Tracking missing'

export type ProcurementTask = {
  id: string
  title: string
  description: string
  projectId: string
  projectNumber: string
  customer: string
  assignedToUserId: string
  assignedUser: string
  priority: ProcurementPriority
  dueDate: string
  status: ProcurementStatus
  relatedRecordType: RelatedRecordType
  relatedRecordId: string
  relatedHref: string
  createdAt: string
  updatedAt: string
  completedAt?: string
}

export type ProcurementDueOut = {
  id: string
  title: string
  projectId: string
  projectNumber: string
  customer: string
  ownerUserId: string
  owner: string
  dueDate: string
  status: ProcurementStatus
  nextAction: string
  waitingOn: WaitingOn
  createdAt: string
  updatedAt: string
}

export type VendorUpdate = {
  id: string
  vendor: string
  poId: string
  poNumber: string
  projectId: string
  projectNumber: string
  issueType: string
  lastUpdateDate: string
  daysSinceUpdate: number
  nextAction: string
