export type ProcurementRisk = {
  id: string
  projectId: string
  projectNumber: string
  customer: string
  poId: string
  lineItemId: string
  manufacturer: string
  partNumber: string
  description: string
  quantity: number
  requiredByDate: string
  currentEta: string
  riskReason: string
  severity: RiskSeverity
  status: ProcurementStatus
  relatedHref: string
}

export type ProcurementShipment = {
  id: string
