  projectId: string
  projectNumber: string
  poId: string
  poNumber: string
  carrier: string
  trackingNumber: string
  estimatedDeliveryDate: string
  actualDeliveryDate: string
  deliveryStatus: ShipmentStatus
  exceptionNotes: string
  relatedHref: string
