import type { Project } from '../types'
export type ProjectRecord = { project_id: string; data: Project | null; revision: number; deleted: boolean }
const records = new Map<string, ProjectRecord>()
let initializing: Promise<void> | undefined
let database: Promise<IDBDatabase> | undefined
let persistence: Promise<void> = Promise.resolve()
let channel: BroadcastChannel | undefined

function db() {
  return database ??= new Promise((resolve, reject) => {
    const request = indexedDB.open('atlas-project-cache-v2', 1)
    request.onupgradeneeded = () => request.result.createObjectStore('projects', { keyPath: 'project_id' })
    request.onsuccess = () => resolve(request.result)
    request.onerror = () => reject(request.error)
  })
}
function notify() { window.dispatchEvent(new Event('cronos:projects-changed')) }
export function initializeProjectCache() {
  return initializing ??= (async () => {
    if (typeof BroadcastChannel !== 'undefined') {
      channel = new BroadcastChannel('atlas-project-cache-v2')
      channel.onmessage = event => { mergeProjectRecords(event.data, false) }
    }
    try {
      const database = await db()
      const saved = await new Promise<ProjectRecord[]>((resolve, reject) => {
        const request = database.transaction('projects').objectStore('projects').getAll()
        request.onsuccess = () => resolve(request.result)
        request.onerror = () => reject(request.error)
      })
      mergeProjectRecords(saved, false)
    } catch { /* Online confirmed records remain usable when browser storage is unavailable. */ }
  })()
}
export function cachedProjects(): Project[] {
  void initializeProjectCache()
  return [...records.values()].filter(row => !row.deleted && row.data).map(row => row.data!)
}
export function cachedProject(id: string) { return records.get(id)?.data ?? undefined }
export function mergeProjectRecords(incoming: ProjectRecord[], broadcast = true) {
  if (!Array.isArray(incoming)) return
  const changed: ProjectRecord[] = []
  for (const row of incoming) {
    if (!row || !row.project_id || !Number.isSafeInteger(row.revision) || row.revision < 1 || (!row.deleted && (!row.data || row.data.id !== row.project_id))) continue
    const previous = records.get(row.project_id)
    if (previous && previous.revision > row.revision) continue
    // A funds workspace can enrich an equal-version project; an older read cannot remove it.
    if (previous && previous.revision === row.revision) {
      if (!row.data?.managedFunds || previous.data?.managedFunds) continue
    }
    const next = { ...row, data: row.deleted ? null : { ...row.data!, recordRevision: row.revision } }
    records.set(row.project_id, next)
    changed.push(next)
  }
  if (!changed.length) return
  persistence = persistence.catch(() => {}).then(async () => {
    const database = await db()
    await new Promise<void>((resolve, reject) => {
      const transaction = database.transaction('projects', 'readwrite')
      const store = transaction.objectStore('projects')
      for (const row of changed) {
        const request = store.get(row.project_id)
        request.onsuccess = () => {
          const existing = request.result as ProjectRecord | undefined
          if (!existing || existing.revision < row.revision || (existing.revision === row.revision && row.data?.managedFunds)) store.put(row)
        }
      }
      transaction.oncomplete = () => resolve()
      transaction.onerror = () => reject(transaction.error)
      transaction.onabort = () => reject(transaction.error)
    })
  }).catch(() => {})
  if (broadcast) channel?.postMessage(changed)
  notify()
}

import type { Project } from '../types'
import type { ProjectRecord } from './projectCache'
import { cachedProjects, mergeProjectRecords } from './projectCache'
import { sameRecord, conflictMessage } from './confirmedCollection.mjs'
export type ProjectSaveOptions = {
  changedIds?: string[]; expectedItems?: unknown[]; normalizeItem?: (item: any) => unknown
  rebaseProject?: (current: Project) => Project; quoteId?: string; approvalStatus?: string
}
function failure(error: any) {
  if (['42P01','42883','PGRST202','PGRST205'].includes(error?.code)) return new Error('The Atlas project database update has not been installed. Apply the accompanying Supabase migration before saving.')
  if (['57014','55P03'].includes(error?.code)) return new Error('Supabase could not complete this save in time. No success was confirmed. Refresh the project and retry. If this continues, contact your Atlas administrator.')
  return new Error(error?.message || 'Project save failed.')
}
export async function refreshProjectRecords(client: any) {
  // Explicit tombstones make deletion safe even when list responses arrive out of order.
  for (let offset = 0; ; offset += 500) {
    const {data,error} = await client.from('atlas_project_records').select('project_id,data,revision,deleted').order('project_id').range(offset,offset+499)
    if (error) throw failure(error)
    if (!Array.isArray(data)) throw new Error('Supabase returned an invalid project list.')
    mergeProjectRecords(data)
    if (data.length < 500) break
  }
  return cachedProjects()
}
export async function readProjectRecord(client: any, id: string): Promise<ProjectRecord | null> {
  const {data,error} = await client.from('atlas_project_records').select('project_id,data,revision,deleted').eq('project_id',id).maybeSingle()
  if (error) throw failure(error)
  if (data) mergeProjectRecords([data])
  return data
}
export async function saveProjectRecords(client: any, items: Project[], options: ProjectSaveOptions) {
  const ids = options.changedIds
  if (!ids || ids.length !== 1) throw new Error('Save one project at a time. Whole-project-list restores are disabled to protect newer work.')
  const id = ids[0], proposed = items.find(p => p.id === id)
  const baseline = (options.expectedItems as Project[] | undefined)?.find(p => p.id === id)
  for (let attempt=0;attempt<3;attempt++) {
    const row = await readProjectRecord(client,id)
    if (row?.deleted) throw new Error('This project was deleted. Nothing was saved.')
    const current = row?.data ?? undefined
    let next = proposed
    if (options.rebaseProject) {
      if (!current) throw new Error('This opportunity was deleted. Nothing was saved.')
      next = options.rebaseProject(current)
    } else {
      const normalize = options.normalizeItem ?? ((p:Project) => p)
      if (current && (!baseline || baseline.recordRevision !== row!.revision || !sameRecord(normalize(current),normalize(baseline)))) throw new Error(conflictMessage)
      if (!current && baseline) throw new Error(conflictMessage)
      // The submitted project's version must remain its original version, too.
      if (current && proposed && proposed.recordRevision !== row!.revision) throw new Error(conflictMessage)
    }
    const {data,error} = await client.rpc('atlas_save_project',{
      p_project_id:id,p_expected_revision:row?.revision ?? -1,p_project:next ?? null,
      p_quote_id:options.quoteId ?? null,p_approval_status:options.approvalStatus ?? null,p_delete:!next,
    })
    if (error) {
      if (error.code === '40001' && options.rebaseProject) continue
      throw failure(error)
    }
    if (!data || data.project_id !== id || data.revision !== (row?.revision ?? 0)+1 || (!data.deleted && !data.data)) throw new Error('Supabase did not confirm the saved project. Refresh before retrying.')
    mergeProjectRecords([data])
    return cachedProjects()
  }
  throw new Error(conflictMessage)
}

import { cachedProjects } from './projectCache'
import { createDocumentAudit, documentValue, finishDocumentAudit } from './documentGeneration'

const exportKeys = [
  ['Projects', 'cronos.projects'],
  ['Customer Orders', 'cronos.customerOrders'],
  ['Vendor Directory', 'cronos.vendorDirectory'],
  ['Part Catalog', 'cronos.partCatalog'],
  ['Users', 'cronos.users'],
  ['Public Lookup Audit', 'cronos.publicLookupAuditLog'],
]

export function downloadExportCsv() {
  const audit = createDocumentAudit('Data Export CSV', 'cronos-export.csv')
  const rows = [
    ['Dataset', 'Records'],
    ...exportKeys.map(([label, key]) => [documentValue(label), String(recordCount(key))]),
  ]
  const csv = toCsv(rows)
  const blob = new Blob([csv], { type: 'text/csv;charset=utf-8' })
  const url = window.URL.createObjectURL(blob)
  const link = document.createElement('a')
  link.href = url
  link.download = 'cronos-export.csv'
  document.body.append(link)
  link.click()
  link.remove()
  window.URL.revokeObjectURL(url)
  finishDocumentAudit(audit)
}

function recordCount(key: string) {
  if (key === 'cronos.projects') return cachedProjects().length
  try {
    const value = JSON.parse(window.localStorage.getItem(key) ?? '[]') as unknown
    return Array.isArray(value) ? value.length : value ? 1 : 0
  } catch {
    return 0
  }
}

function toCsv(rows: string[][]) {
  return rows.map(row => row.map(cell => `"${cell.replaceAll('"', '""')}"`).join(',')).join('\n')
}

export function assertManagedApprovalIntent(previous, next, approvalQuoteId) {
  const byId = new Map((previous.quotes || []).map(q=>[q.id,q]))
  for (const quote of next.quotes || []) {
    const old=byId.get(quote.id)
    if (quote.status !== (old?.status || 'Quoted') && quote.id !== approvalQuoteId) throw new Error('Approval changes require the explicit Approve or Unapprove action.')
    const lines=new Map((old?.lines || []).map(l=>[l.id,l]))
    for (const line of quote.lines || []) {
      const expected=lines.get(line.id)?.approved ?? (old?.status === 'Customer Approved')
      if (Boolean(line.approved) !== Boolean(expected) && quote.id !== approvalQuoteId) throw new Error('Line approval changes require an explicit approval action.')
    }
    if (quote.id === approvalQuoteId && !['Quoted','Customer Approved'].includes(quote.status)) throw new Error('Invalid quote approval status.')
    if (quote.id === approvalQuoteId && quote.lines.some(l=>Boolean(l.approved)!==(quote.status==='Customer Approved'))) throw new Error('Approval action does not match quote lines.')
  }
  if (approvalQuoteId && !next.quotes.some(q=>q.id===approvalQuoteId)) throw new Error('Quote to approve was not found.')
}

-- Apply once in Supabase SQL Editor BEFORE deploying the matching Atlas build.
-- Transactional cutover: preserves projects/all as an immutable pre-cutover backup.
-- Rerunning does not overwrite newer records or resurrect deleted projects.
begin;
lock table public.app_records in share row exclusive mode;

create table if not exists public.atlas_project_records (
  project_id text primary key,
  data jsonb,
  revision bigint not null check(revision > 0),
  deleted boolean not null default false,
  updated_at timestamptz not null default clock_timestamp(),
  check ((deleted and data is null) or (not deleted and jsonb_typeof(data)='object' and data->>'id'=project_id))
);
create table if not exists public.atlas_quote_approval_events (
  id bigint generated always as identity primary key,
  project_id text not null references public.atlas_project_records(project_id),
  quote_id text not null,
  previous_status text,
  new_status text,
  project_revision bigint not null,
  actor_id uuid,
  occurred_at timestamptz not null default clock_timestamp(),
  reason text not null
);
create index if not exists atlas_quote_approval_events_project on public.atlas_quote_approval_events(project_id,occurred_at);
alter table public.atlas_project_records enable row level security;
alter table public.atlas_quote_approval_events enable row level security;
revoke all on public.atlas_project_records,public.atlas_quote_approval_events from public,anon,authenticated;
grant select on public.atlas_project_records,public.atlas_quote_approval_events to authenticated;
grant select,insert,update on public.atlas_project_records to service_role;
grant select,insert on public.atlas_quote_approval_events to service_role;
grant usage,select on sequence public.atlas_quote_approval_events_id_seq to service_role;

create or replace function public.atlas_project_access() returns boolean
language sql stable set search_path=public as $$
  select auth.role()='service_role' or
    (auth.uid() is not null and coalesce(auth.jwt()->'app_metadata'->>'active','true')<>'false'
      and coalesce(auth.jwt()->'app_metadata'->>'atlas_role','') in ('admin','procurement','engineering','sales'))
$$;
revoke all on function public.atlas_project_access() from public;
grant execute on function public.atlas_project_access() to authenticated,service_role;
drop policy if exists atlas_project_read on public.atlas_project_records;
create policy atlas_project_read on public.atlas_project_records for select to authenticated using(public.atlas_project_access());
drop policy if exists atlas_approval_read on public.atlas_quote_approval_events;
create policy atlas_approval_read on public.atlas_quote_approval_events for select to authenticated using(public.atlas_project_access());

do $$ declare source jsonb; begin
  select data into source from public.app_records where record_type='projects' and record_key='all';
  if source is null or jsonb_typeof(source)<>'array' then raise exception 'Missing or invalid projects/all: migration stopped without changes'; end if;
  if exists(select 1 from jsonb_array_elements(source) p where coalesce(p->>'id','')='') or
     exists(select 1 from jsonb_array_elements(source) p group by p->>'id' having count(*)>1) then
    raise exception 'Missing or duplicate project IDs: migration stopped without changes';
  end if;
  insert into public.atlas_project_records(project_id,data,revision)
    select p->>'id',jsonb_set(p-'managedFunds','{recordRevision}','1'::jsonb),1 from jsonb_array_elements(source) p
    on conflict(project_id) do nothing;
end $$;

-- Old builds cannot overwrite the backup or the new store.
create or replace function public.atlas_freeze_legacy_projects() returns trigger
language plpgsql set search_path=public as $$ begin
  if (tg_op<>'INSERT' and old.record_type='projects' and old.record_key='all') or
     (tg_op<>'DELETE' and new.record_type='projects' and new.record_key='all') then
    raise exception 'Atlas has been updated. Reload Atlas before saving. Nothing was saved.' using errcode='P0001';
  end if;
  if tg_op='DELETE' then return old; end if; return new;
end $$;
drop trigger if exists atlas_freeze_legacy_projects on public.app_records;
create trigger atlas_freeze_legacy_projects before insert or update or delete on public.app_records for each row execute function public.atlas_freeze_legacy_projects();
create or replace function public.atlas_merge_standard_projects(p_projects jsonb) returns jsonb
language plpgsql security definer set search_path=public as $$ begin
  raise exception 'Atlas has been updated. Reload Atlas before saving. Nothing was saved.';
end $$;
revoke all on function public.atlas_merge_standard_projects(jsonb) from public,anon,authenticated,service_role;

-- Callers supply the original project version. Approval intent is separate from content.
create or replace function public.atlas_save_project(
  p_project_id text, p_expected_revision bigint, p_project jsonb,
  p_quote_id text default null, p_approval_status text default null, p_delete boolean default false
) returns jsonb language plpgsql security definer set search_path=public set lock_timeout='4s' as $$
declare oldrow public.atlas_project_records; next_revision bigint; q jsonb; prior jsonb; l jsonb; prior_line jsonb; oldstatus text;
begin
  if not public.atlas_project_access() then raise exception 'Sign in to Atlas before saving.' using errcode='42501'; end if;
  if coalesce(p_project_id,'')='' or p_expected_revision is null then raise exception 'Project identity and expected revision are required'; end if;
  perform pg_advisory_xact_lock(hashtextextended('atlas-project:'||p_project_id,0));
  select * into oldrow from public.atlas_project_records where project_id=p_project_id for update;
  if oldrow.deleted or coalesce(oldrow.revision,-1)<>p_expected_revision then raise exception 'Project conflict. Reload and review the latest version.' using errcode='40001'; end if;
  if oldrow.data->>'projectType' in ('Managed Funds','Checkbook') or p_project->>'projectType' in ('Managed Funds','Checkbook') then raise exception 'Managed Funds requires its authenticated API'; end if;
  if p_approval_status is not null and (p_quote_id is null or p_approval_status not in ('Quoted','Customer Approved')) then raise exception 'Invalid approval action'; end if;
  next_revision:=coalesce(oldrow.revision,0)+1;
  if p_delete then
    if oldrow.project_id is null or p_project is not null then raise exception 'Invalid project deletion'; end if;
    update public.atlas_project_records set data=null,deleted=true,revision=next_revision,updated_at=clock_timestamp() where project_id=p_project_id;
    insert into public.atlas_quote_approval_events(project_id,quote_id,previous_status,new_status,project_revision,actor_id,reason)
      select p_project_id,qv->>'id',qv->>'status',null,next_revision,auth.uid(),'Project deleted' from jsonb_array_elements(coalesce(oldrow.data->'quotes','[]')) qv;
    return jsonb_build_object('project_id',p_project_id,'data',null,'revision',next_revision,'deleted',true);
  end if;
  if p_project is null or jsonb_typeof(p_project)<>'object' or p_project->>'id' is distinct from p_project_id or jsonb_typeof(p_project->'quotes') is distinct from 'array' then raise exception 'Invalid project'; end if;
  if exists(select 1 from jsonb_array_elements(p_project->'quotes') v where coalesce(v->>'id','')='') or exists(select 1 from jsonb_array_elements(p_project->'quotes') v group by v->>'id' having count(*)>1) then raise exception 'Quote IDs must be unique'; end if;
  if p_approval_status is not null and not exists(select 1 from jsonb_array_elements(coalesce(oldrow.data->'quotes','[]')) v where v->>'id'=p_quote_id) then raise exception 'Quote to approve was not found'; end if;
  for q in select value from jsonb_array_elements(p_project->'quotes') loop
    select v into prior from jsonb_array_elements(coalesce(oldrow.data->'quotes','[]')) v where v->>'id'=q->>'id';
    oldstatus:=prior->>'status';
    if q->>'id'=p_quote_id and p_approval_status is not null then
      if q->>'status' is distinct from p_approval_status then raise exception 'Approval action does not match quote status'; end if;
    elsif prior is not null then
      if q->>'status' is distinct from oldstatus then raise exception 'Approval changes require the explicit Approve or Unapprove action'; end if;
    elsif q->>'status' is distinct from 'Quoted' then raise exception 'New quotes must start unapproved'; end if;
    for l in select value from jsonb_array_elements(coalesce(q->'lines','[]')) loop
      select v into prior_line from jsonb_array_elements(coalesce(prior->'lines','[]')) v where v->>'id'=l->>'id';
      if q->>'id'=p_quote_id and p_approval_status is not null then
        if coalesce(l->>'approved','false') is distinct from (case when p_approval_status='Customer Approved' then 'true' else 'false' end) then raise exception 'Approval action does not match quote lines'; end if;
      elsif coalesce(l->>'approved','false') is distinct from coalesce(prior_line->>'approved',case when q->>'status'='Customer Approved' then 'true' else 'false' end) then
        raise exception 'Line approval changes require the explicit approval action';
      end if;
    end loop;
  end loop;
  for prior in select value from jsonb_array_elements(coalesce(oldrow.data->'quotes','[]')) loop
    if not exists(select 1 from jsonb_array_elements(p_project->'quotes') v where v->>'id'=prior->>'id') and (p_quote_id is distinct from prior->>'id' or p_approval_status is not null) then raise exception 'Quote deletion requires an explicit quote action'; end if;
  end loop;
  p_project:=jsonb_set(jsonb_set(p_project-'managedFunds','{recordRevision}',to_jsonb(next_revision)),'{updatedAt}',to_jsonb(clock_timestamp()));
  -- The flat legacy line list is derived, never an independent approval authority.
  p_project:=jsonb_set(p_project,'{quoteLines}',coalesce((select jsonb_agg(b.l order by a.qi,b.li) from jsonb_array_elements(p_project->'quotes') with ordinality a(qv,qi) cross join lateral jsonb_array_elements(coalesce(qv->'lines','[]')) with ordinality b(l,li)),'[]'));
  insert into public.atlas_project_records(project_id,data,revision) values(p_project_id,p_project,next_revision)
    on conflict(project_id) do update set data=excluded.data,revision=excluded.revision,updated_at=clock_timestamp();
  insert into public.atlas_quote_approval_events(project_id,quote_id,previous_status,new_status,project_revision,actor_id,reason)
    select p_project_id,coalesce(n->>'id',o->>'id'),o->>'status',n->>'status',next_revision,auth.uid(),
      case when n is null then 'Quote deleted' when o is null then 'Quote created' else 'Explicit approval action' end
    from jsonb_array_elements(coalesce(oldrow.data->'quotes','[]')) o full join jsonb_array_elements(p_project->'quotes') n on o->>'id'=n->>'id'
    where o->>'status' is distinct from n->>'status';
  return jsonb_build_object('project_id',p_project_id,'data',p_project,'revision',next_revision,'deleted',false);
end $$;
revoke all on function public.atlas_save_project(text,bigint,jsonb,text,text,boolean) from public,anon;
grant execute on function public.atlas_save_project(text,bigint,jsonb,text,text,boolean) to authenticated,service_role;

-- Keep the existing ledger and history checks; lock/write only this project.
create or replace function public.atlas_commit_managed_funds(p_project_id text,p_expected_revision bigint,p_previous_project jsonb,p_project jsonb,p_state jsonb)
returns jsonb language plpgsql security definer set search_path=public as $$
declare current_project jsonb; project_revision bigint; old_state jsonb; old_revision bigint; new_revision bigint; item jsonb; allocation jsonb; historical jsonb;
begin
  perform pg_advisory_xact_lock(hashtextextended('atlas-project:'||p_project_id,0));
  if exists(select 1 from atlas_project_records where project_id=p_project_id and deleted) then raise exception 'Project conflict'; end if;
  select data,revision into current_project,project_revision from atlas_project_records where project_id=p_project_id for update;
  if (current_project - 'managedFunds') is distinct from (p_previous_project - 'managedFunds') then raise exception 'Project conflict'; end if;
  select state,revision into old_state,old_revision from atlas_managed_funds where project_id=p_project_id for update;
  if coalesce(old_revision,-1) <> p_expected_revision then raise exception 'Revision conflict'; end if;
  if p_state->>'projectId' <> p_project_id or p_project->>'id' <> p_project_id or p_project->>'projectType'<>'Managed Funds' then raise exception 'Invalid project identity'; end if;
  if old_state is not null then
    if p_state->'originalFunding' is distinct from old_state->'originalFunding' then raise exception 'Original funding is immutable'; end if;
    foreach historical in array array['"transactions"'::jsonb,'"audit"'::jsonb,'"commands"'::jsonb] loop
      for item in select value from jsonb_array_elements(old_state->(historical #>> '{}')) loop
        if not (p_state->(historical #>> '{}') @> jsonb_build_array(item)) then raise exception 'Financial history is append-only'; end if;
      end loop;
    end loop;
    for item in select value from jsonb_array_elements(old_state->'actions') loop
      if not exists(select 1 from jsonb_array_elements(p_state->'actions') a where a->>'id'=item->>'id' and a->>'number'=item->>'number') then raise exception 'Actions cannot be removed or renumbered'; end if;
    end loop;
    for item in select value from jsonb_array_elements(old_state->'invoices') loop
      if not exists(select 1 from jsonb_array_elements(p_state->'invoices') i where i->>'id'=item->>'id' and i->'allocations'=item->'allocations' and i->>'number'=item->>'number' and i->'total'=item->'total' and (item->>'status'='Draft' or i=item)) then raise exception 'Invoice history cannot be rewritten'; end if;
    end loop;
    for item in select value from jsonb_array_elements(old_state->'documents') loop
      if not (p_state->'documents' @> jsonb_build_array(item)) then raise exception 'Documents cannot be removed'; end if;
    end loop;
  else
    insert into atlas_managed_funds_legacy_backups(project_id,source) values(p_project_id,coalesce(current_project,p_project)) on conflict do nothing;
  end if;
  new_revision := coalesce(old_revision,0)+1;
  p_state := jsonb_set(p_state,'{revision}',to_jsonb(new_revision));
  insert into atlas_managed_funds(project_id,revision,state) values(p_project_id,new_revision,p_state)
  on conflict(project_id) do update set revision=excluded.revision,state=excluded.state,updated_at=now();
  for item in select value from jsonb_array_elements(p_state->'actions') loop
    insert into atlas_managed_funds_actions(id,project_id,action_number,data) values(item->>'id',p_project_id,item->>'number',item)
    on conflict(id) do update set data=excluded.data where atlas_managed_funds_actions.project_id=excluded.project_id;
  end loop;
  for item in select value from jsonb_array_elements(p_state->'transactions') loop
    insert into atlas_managed_funds_transactions(id,project_id,action_id,data) values(item->>'id',p_project_id,item->>'actionId',item) on conflict do nothing;
  end loop;
  for item in select value from jsonb_array_elements(p_state->'audit') loop
    insert into atlas_managed_funds_audit(id,project_id,data) values(item->>'id',p_project_id,item) on conflict do nothing;
  end loop;
  for item in select value from jsonb_array_elements(p_state->'invoices') loop
    insert into atlas_managed_funds_invoices(id,project_id,invoice_number,data) values(item->>'id',p_project_id,item->>'number',item)
    on conflict(id) do update set data=excluded.data where atlas_managed_funds_invoices.project_id=excluded.project_id;
    for allocation in select value from jsonb_array_elements(item->'allocations') loop
      insert into atlas_managed_funds_invoice_allocations(id,project_id,invoice_id,action_id,amount_cents,data) values(allocation->>'id',p_project_id,item->>'id',allocation->>'actionId',(allocation->>'amount')::bigint,allocation) on conflict do nothing;
    end loop;
  end loop;
  for item in select value from jsonb_array_elements(p_state->'documents') loop
    insert into atlas_managed_funds_documents(id,project_id,action_id,data) values(item->>'id',p_project_id,item->>'actionId',item) on conflict do nothing;
  end loop;
  for item in select value from jsonb_array_elements(coalesce(p_project->'quotes','[]')) loop
    insert into atlas_managed_funds_document_links(project_id,action_id,document_kind,source_id) values(p_project_id,item->>'actionId','Customer Quote',item->>'id') on conflict do nothing;
  end loop;
  for item in select value from jsonb_array_elements(coalesce(p_project->'purchaseOrders','[]')) loop
    insert into atlas_managed_funds_document_links(project_id,action_id,document_kind,source_id) values(p_project_id,item->>'actionId','Purchase Order',item->>'id') on conflict do nothing;
  end loop;
  p_project := jsonb_set(p_project - 'managedFunds','{managedFundsRevision}',to_jsonb(new_revision));
  p_project:=jsonb_set(p_project,'{quoteLines}',coalesce((select jsonb_agg(b.l order by a.qi,b.li) from jsonb_array_elements(coalesce(p_project->'quotes','[]')) with ordinality a(qv,qi) cross join lateral jsonb_array_elements(coalesce(qv->'lines','[]')) with ordinality b(l,li)),'[]')); 
  project_revision:=coalesce(project_revision,0)+1;
  p_project:=jsonb_set(jsonb_set(p_project,'{recordRevision}',to_jsonb(project_revision)),'{updatedAt}',to_jsonb(clock_timestamp()));
  insert into atlas_project_records(project_id,data,revision) values(p_project_id,p_project,project_revision)
    on conflict(project_id) do update set data=excluded.data,revision=excluded.revision,updated_at=clock_timestamp();
  return jsonb_build_object('revision',new_revision,'recordRevision',project_revision);
end $$;
revoke all on function public.atlas_commit_managed_funds(text,bigint,jsonb,jsonb,jsonb) from public,anon,authenticated;
grant execute on function public.atlas_commit_managed_funds(text,bigint,jsonb,jsonb,jsonb) to service_role;


-- Project and ledger must come from a single database snapshot.
create or replace function public.atlas_read_managed_workspace(p_project_id text) returns jsonb
language sql stable set search_path=public as $$
  select jsonb_build_object('project',p.data,'state',case when f.project_id is null then null else jsonb_set(f.state,'{revision}',to_jsonb(f.revision)) end)
  from atlas_project_records p left join atlas_managed_funds f on f.project_id=p.project_id
  where p.project_id=p_project_id and not p.deleted
$$;
revoke all on function public.atlas_read_managed_workspace(text) from public,anon,authenticated;
grant execute on function public.atlas_read_managed_workspace(text) to service_role;
notify pgrst, 'reload schema';
commit;

