 create schema storage;create table storage.buckets(id text primary key,name text,public boolean,file_size_limit bigint);
 create schema auth;create function auth.jwt() returns jsonb language sql stable as $$select coalesce(nullif(current_setting('request.jwt.claims',true),''),'{}')::jsonb$$;
 create function auth.uid() returns uuid language sql stable as $$select (auth.jwt()->>'sub')::uuid$$;
 create function auth.role() returns text language sql stable as $$select auth.jwt()->>'role'$$;
 grant usage on schema auth to authenticated,service_role;grant execute on all functions in schema auth to authenticated,service_role;
 create table app_records(record_type text,record_key text,data jsonb,updated_at timestamptz default now(),unique(record_type,record_key));
 grant usage on schema public to anon,authenticated,service_role;grant select,insert,update,delete on app_records to anon,authenticated,service_role;`)
 await db.query("insert into app_records values('projects','all',$1,now())",[JSON.stringify(projects)])
