 await db.query("select set_config('request.jwt.claims',$1,false)",[JSON.stringify({role:'authenticated',sub:'aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa',app_metadata:{atlas_role:'admin',active:true}})])
