where r.record_type='projects' and r.record_key='all' and
 (n.project_id is null or (n.revision=1 and n.data-'recordRevision' is distinct from p-'recordRevision'-'managedFunds'));
select data->>'projectNumber' as project_number,data->>'projectName' as project_name,revision,updated_at
