import { onUnmounted, ref } from 'vue'
import { onBeforeRouteLeave } from 'vue-router'

/** Keep navigation and document export behind the same database confirmation as Save. */
export function useDatabaseSave() {
  const savePending = ref(false)
  const saveStatus = ref('')
  let queued = 0
  let failure: unknown
  let tail: Promise<unknown> = Promise.resolve()
  function trackSave<T>(work: () => Promise<T>): Promise<T> {
    if (!queued) failure = undefined
    queued += 1
    savePending.value = true
    saveStatus.value = 'Saving to database…'
    const pending = tail.catch(() => {}).then(work)
    tail = pending
    return pending.then(value => {
      if (!failure) saveStatus.value = 'Saved to database.'
      return value
    }, error => {
      failure = error
      saveStatus.value = 'Save not confirmed. Your changes still need to be saved.'
      throw error
    }).finally(() => {
      queued -= 1
      savePending.value = queued > 0
      if (queued) saveStatus.value = 'Saving to database…'
      else if (failure) saveStatus.value = 'Save not confirmed. Your changes still need to be saved.'
    })
  }
  async function waitForSave() {
    await tail
    if (failure) throw failure
  }
  onBeforeRouteLeave(async () => {
    if (!savePending.value) return
    try { await waitForSave() } catch { return false }
  })
  const beforeUnload = (event: BeforeUnloadEvent) => {
    if (savePending.value) { event.preventDefault(); event.returnValue = '' }
  }
  window.addEventListener('beforeunload', beforeUnload)
  onUnmounted(() => window.removeEventListener('beforeunload', beforeUnload))
  return { trackSave, waitForSave, savePending, saveStatus }
}

import { getSupabaseAccessToken } from './supabaseAuth'
export type PilotCollection = 'customers' | 'customer-addresses' | 'vendors'
const writes = new Map<PilotCollection, Promise<unknown>>()
const versions = new Map<PilotCollection, number>()
export async function loadPilotCollection<T>(collection: PilotCollection): Promise<T[]> {
  await writes.get(collection)?.catch(() => {})
  const version = versions.get(collection)
  const token = await getSupabaseAccessToken()
  if (!token) throw new Error('Sign in to load the directory.')
  const response = await fetch(`/api/data/${collection}/bulk`, { headers: { Authorization: `Bearer ${token}` } })
  const payload = await response.json()
  if (!response.ok || !Array.isArray(payload.records)) throw new Error(payload.error || 'Directory load failed.')
  if (versions.get(collection) !== version) return loadPilotCollection<T>(collection)
  return payload.records
}
export async function replacePilotCollection<T>(collection: PilotCollection, records: T[], expectedRecords: T[]): Promise<T[]> {
  const body = JSON.stringify({ records, expectedRecords })
  const prior = writes.get(collection)
  versions.set(collection, (versions.get(collection) ?? 0) + 1)
  const pending = (async () => {
    await prior?.catch(() => {})
    const token = await getSupabaseAccessToken()
    if (!token) throw new Error('An authenticated session is required to save business data.')
    const response = await fetch(`/api/data/${collection}/bulk`, {
      method: 'PUT', headers: { Authorization: `Bearer ${token}`, 'Content-Type': 'application/json' }, body,
    })
    const payload = await response.json()
    if (!response.ok || !Array.isArray(payload.records)) throw new Error(payload.error || 'The database did not confirm this save.')
    return payload.records as T[]
  })()
  writes.set(collection, pending)
  try { return await pending } finally { if (writes.get(collection) === pending) writes.delete(collection) }
}

export async function createVendorRecord<T>(vendor: T, duplicateOverride = false) {
  const token = await getSupabaseAccessToken()
  if (!token) throw new Error('You must be signed in to add a vendor.')
  const response = await fetch('/api/data/vendors', {
    method: 'POST',
    headers: { Authorization: `Bearer ${token}`, 'Content-Type': 'application/json' },
    body: JSON.stringify({ vendor, duplicateOverride }),
  })
  const payload = await response.json().catch(() => ({})) as {
    error?: string; vendor?: T; message?: string; possibleDuplicate?: { legal_name?: string }
  }
  if (!response.ok) {
    const error = new Error(payload.error || 'Unable to add vendor.') as Error & { status?: number; possibleDuplicate?: { legal_name?: string } }
    error.status = response.status
    error.possibleDuplicate = payload.possibleDuplicate
    throw error
  }
  return { vendor: payload.vendor as T, message: payload.message || 'Vendor added.' }
}

