const REMOTE_TYPE = 'customer_orders'
const REMOTE_KEY = 'all'
let hydrationStarted = false

export const customerOrderStatuses: CustomerOrderStatus[] = [
  'Pending Procurement',
  'PO Issued',
  'Backordered',
  'Awaiting Vendor Shipment',
  'In Transit to Cronos',
  'Received at Cronos',
  'Kitted',
  'Partially Shipped',
  'Shipped to Customer',
