  if (hydrationStarted || typeof window === 'undefined') return
  hydrationStarted = true
  hydration = Promise.all([loadPilotCollection<CustomerRecord>('customers').then(items => { writeLocalCollection(CUSTOMER_STORAGE_KEY, items.map(normalizeCustomerRecord)); window.dispatchEvent(new Event('cronos:customers-changed')) }),
  loadPilotCollection<CustomerAddressRecord>('customer-addresses').then(items => { writeLocalCollection(ADDRESS_STORAGE_KEY, items.map(normalizeAddressRecord)); window.dispatchEvent(new Event('cronos:customers-changed')) })])
  void hydration.catch(reportPilotSyncError)
}

export async function ensureCustomersLoaded() {
  hydrateCustomers()
  await hydration
}

export function loadCustomers() {
  hydrateCustomers()
  return readLocalCollection<CustomerRecord>(CUSTOMER_STORAGE_KEY).map(normalizeCustomerRecord)
}

export function loadCustomerAddresses(customerId?: string) {
  hydrateCustomers()
  const addresses = readLocalCollection<CustomerAddressRecord>(ADDRESS_STORAGE_KEY).map(normalizeAddressRecord)
  return customerId ? addresses.filter(address => address.customerId === customerId && address.active) : addresses
}

let customerSync: Promise<void> = Promise.resolve()
export function syncCustomersFromProjects(projects: Project[]) {
  const pending = customerSync.catch(() => {}).then(() => syncCustomersConfirmed(projects))
  customerSync = pending
  return pending
}
async function syncCustomersConfirmed(projects: Project[]) {
  hydrateCustomers(); await hydration
  const customers = loadCustomers()
  const addresses = loadCustomerAddresses()
  let nextCustomers = [...customers]
  let nextAddresses = [...addresses]
  let changed = false

  projects.forEach(project => {
    const company = project.customer.trim()
    if (!company) return
    let customer = nextCustomers.find(record => record.id === project.customerId)
      ?? nextCustomers.find(record => normalizeCompany(record.legalCompanyName) === normalizeCompany(company))
    const now = new Date().toISOString()
    if (!customer) {
      customer = normalizeCustomerRecord({
        id: project.customerId || crypto.randomUUID(),
        legalCompanyName: company,
        displayName: company,
        customerNumber: project.customerNumber ?? '',
        primaryContact: project.customerContactName,
        primaryEmail: project.customerEmail,
        primaryPhone: project.customerPhone,
        website: project.customerWebsite ?? '',
        active: true,
        createdAt: now,
        updatedAt: now,
        useCount: 0,
        lastUsedAt: '',
      })
      nextCustomers.push(customer)
      changed = true
    }

    const hasAddress = project.customerAddress1 || project.customerCity || project.customerZip
    const linkedAddress = nextAddresses.find(address => address.id === project.customerAddressId && address.customerId === customer.id)
    const duplicate = linkedAddress ?? (hasAddress ? nextAddresses.find(address =>
      address.customerId === customer.id &&
      normalizeAddress(address.streetAddress1) === normalizeAddress(project.customerAddress1) &&
      normalizeSearch(address.city) === normalizeSearch(project.customerCity) &&
      normalizeSearch(address.zipCode) === normalizeSearch(project.customerZip),
    ) : undefined)
    if (hasAddress && !duplicate) {
      // A legacy parent must exist in the normalized table before its address.
      if (!(customer as CustomerRecord & {version?: number}).version) {
        nextCustomers = nextCustomers.map(record => record.id === customer.id ? {...record, updatedAt: now} : record)
      }
      nextAddresses.push(normalizeAddressRecord({
        id: project.customerAddressId && !nextAddresses.some(address => address.id === project.customerAddressId)
          ? project.customerAddressId : crypto.randomUUID(),
        customerId: customer.id,
        label: 'Project Site',
        type: 'Project Site',
        contactName: project.customerContactName,
        streetAddress1: project.customerAddress1,
        streetAddress2: project.customerAddress2,
        city: project.customerCity,
        state: project.customerState,
        zipCode: project.customerZip,
        country: project.customerCountry,
        email: project.customerEmail,
        phone: project.customerPhone,
        isPrimary: !nextAddresses.some(address => address.customerId === customer.id && address.isPrimary),
        active: true,
        createdAt: now,
        updatedAt: now,
        useCount: 0,
        lastUsedAt: '',
      }))
      changed = true
    }
  })

  if (changed) {
    await saveCustomers(nextCustomers)
    await saveAddresses(nextAddresses)
  }
}

export function searchCustomerSuggestions(query: string, limit = 10): CustomerSuggestion[] {
  const normalizedQuery = normalizeSearch(query)
  const customers = loadCustomers().filter(customer => customer.active)
  const addresses = loadCustomerAddresses()
  const scored = customers
    .map(customer => {
      const customerAddresses = addresses.filter(address => address.customerId === customer.id)
      const primaryAddress = choosePrimaryAddress(customerAddresses)
      const haystack = [
        customer.legalCompanyName,
        customer.displayName,
        customer.customerNumber,
        customer.primaryContact,
        customer.primaryEmail,
        primaryAddress?.contactName,
        primaryAddress?.city,
        primaryAddress?.state,
        primaryAddress?.streetAddress1,
      ].join(' ')
      const score = normalizedQuery ? (normalizeSearch(haystack).includes(normalizedQuery) ? 10 : 0) : 1 + customer.useCount
      return { customer, primaryAddress, score }
    })
    .filter(item => item.score > 0)
    .sort((a, b) => b.score - a.score || Date.parse(b.customer.lastUsedAt || '') - Date.parse(a.customer.lastUsedAt || ''))
    .slice(0, limit)

  return scored.map(({ customer, primaryAddress }) => ({
    customer,
    primaryAddress,
    label: customer.displayName || customer.legalCompanyName,
    detail: [primaryAddress ? `${primaryAddress.city}, ${primaryAddress.state}` : '', customer.primaryContact ? `Primary Contact: ${customer.primaryContact}` : '']
      .filter(Boolean)
      .join(' | '),
  }))
}

export function rankAddressSuggestions(customerId: string, limit = 8) {
  return loadCustomerAddresses(customerId)
    .sort((a, b) => Number(b.isPrimary) - Number(a.isPrimary) || Date.parse(b.lastUsedAt || '') - Date.parse(a.lastUsedAt || '') || b.useCount - a.useCount)
    .slice(0, limit)
}

export function findCustomerById(id?: string) {
  if (!id) return undefined
  return loadCustomers().find(customer => customer.id === id)
}

export function findAddressById(id?: string) {
  if (!id) return undefined
  return loadCustomerAddresses().find(address => address.id === id)
}

export async function createCustomerFromProject(project: Project, addressType: CustomerAddressType = 'Main Office') {
  hydrateCustomers(); await hydration
  const now = new Date().toISOString()
  const duplicate = findLikelyDuplicateCustomer(project)
  const customer = duplicate ?? normalizeCustomerRecord({
    id: crypto.randomUUID(),
    legalCompanyName: project.customer,
    displayName: project.customer,
    customerNumber: project.customerNumber ?? '',
    primaryContact: project.customerContactName,
    primaryEmail: project.customerEmail,
    primaryPhone: project.customerPhone,
    website: project.customerWebsite ?? '',
    active: true,
    createdAt: now,
    updatedAt: now,
    useCount: 0,
    lastUsedAt: '',
  })
  if (!duplicate) await saveCustomers([...loadCustomers(), customer])

  const address = await upsertAddressForProject(customer.id, project, addressType)
  return { customer, address }
}

export async function upsertAddressForProject(customerId: string, project: Project, type: CustomerAddressType = 'Project Site') {
  await ensureCustomersLoaded()
  const customer = findCustomerById(customerId) as (CustomerRecord & {version?:number}) | undefined
  if(customer && !customer.version) await saveCustomers(loadCustomers().map(c=>c.id===customerId?{...c,updatedAt:new Date().toISOString()}:c))
  const addresses = loadCustomerAddresses()
  const now = new Date().toISOString()
  const existing = findDuplicateAddress(customerId, project)
  if (existing) return existing
  const address = normalizeAddressRecord({
    id: crypto.randomUUID(),
    customerId,
    label: type,
    type,
    contactName: project.customerContactName,
    streetAddress1: project.customerAddress1,
    streetAddress2: project.customerAddress2,
    city: project.customerCity,
    state: project.customerState,
    zipCode: project.customerZip,
    country: project.customerCountry,
    email: project.customerEmail,
    phone: project.customerPhone,
    isPrimary: !addresses.some(item => item.customerId === customerId && item.isPrimary),
    active: true,
    createdAt: now,
    updatedAt: now,
    useCount: 0,
    lastUsedAt: '',
  })
  await saveAddresses([...addresses, address])
  return address
}

export async function rememberCustomerUse(customerId: string, addressId?: string) {
  await ensureCustomersLoaded()
  const now = new Date().toISOString()
  await saveCustomers(loadCustomers().map(customer => (customer.id === customerId ? { ...customer, useCount: customer.useCount + 1, lastUsedAt: now, updatedAt: now } : customer)))
  if (addressId) {
    await saveAddresses(loadCustomerAddresses().map(address => (address.id === addressId ? { ...address, useCount: address.useCount + 1, lastUsedAt: now, updatedAt: now } : address)))
  }
}

export function snapshotFromCustomerAddress(customer: CustomerRecord | undefined, address: CustomerAddressRecord | undefined, project?: Project): CustomerAddressSnapshot {
  // A project can intentionally use a shorter customer name, a different POC, or
  // blank contact fields than the shared directory record. Once a project exists,
  // its current form values are the source of truth for customer-facing documents.
  // Directory values are only defaults when creating a snapshot without a project.
  if (project) {
    return {
      companyName: project.customer,
      contactName: project.customerContactName,
      streetAddress1: project.customerAddress1,
      streetAddress2: project.customerAddress2,
      city: project.customerCity,
      state: project.customerState,
      zipCode: project.customerZip,
      country: project.customerCountry,
      email: project.customerEmail,
      phone: project.customerPhone,
      customerNumber: project.customerNumber,
      website: project.customerWebsite,
      capturedAt: new Date().toISOString(),
    }
  }

  return {
    companyName: customer?.displayName || customer?.legalCompanyName || '',
    contactName: address?.contactName || customer?.primaryContact || '',
    streetAddress1: address?.streetAddress1 || '',
    streetAddress2: address?.streetAddress2 || '',
    city: address?.city || '',
    state: address?.state || '',
    zipCode: address?.zipCode || '',
    country: address?.country || '',
    email: address?.email || customer?.primaryEmail || '',
    phone: address?.phone || customer?.primaryPhone || '',
    customerNumber: customer?.customerNumber || '',
    website: customer?.website || '',
    capturedAt: new Date().toISOString(),
  }
}

export function applyCustomerAddressToProjectInput<T extends Partial<Project>>(input: T, customer: CustomerRecord, address?: CustomerAddressRecord): T {
  return {
    ...input,
    customerId: customer.id,
    customerAddressId: address?.id ?? '',
    customer: customer.displayName || customer.legalCompanyName,
    customerContactName: address?.contactName || customer.primaryContact,
    customerAddress1: address?.streetAddress1 ?? '',
    customerAddress2: address?.streetAddress2 ?? '',
    customerCity: address?.city ?? '',
    customerState: address?.state ?? '',
    customerZip: address?.zipCode ?? '',
    customerCountry: address?.country ?? '',
    customerEmail: address?.email || customer.primaryEmail,
    customerPhone: address?.phone || customer.primaryPhone,
    customerNumber: customer.customerNumber,
    customerWebsite: customer.website,
    customerSnapshot: snapshotFromCustomerAddress(customer, address),
  }
}

export function findLikelyDuplicateCustomer(project: Project) {
  const companyKey = normalizeCompany(project.customer)
  const emailDomain = String(project.customerEmail ?? '').split('@')[1]?.toLowerCase() ?? ''
  const phoneKey = normalizePhone(project.customerPhone)
  return loadCustomers().find(customer =>
    normalizeCompany(customer.legalCompanyName) === companyKey ||
    (emailDomain && customer.primaryEmail.toLowerCase().endsWith(`@${emailDomain}`)) ||
    (phoneKey && normalizePhone(customer.primaryPhone) === phoneKey),
  )
}

export function findDuplicateAddress(customerId: string, project: Project) {
  const streetKey = normalizeAddress(project.customerAddress1)
  const cityKey = normalizeSearch(project.customerCity)
  const zipKey = normalizeSearch(project.customerZip)
  return loadCustomerAddresses(customerId).find(address =>
    normalizeAddress(address.streetAddress1) === streetKey &&
    normalizeSearch(address.city) === cityKey &&
    normalizeSearch(address.zipCode) === zipKey,
  )
}

function choosePrimaryAddress(addresses: CustomerAddressRecord[]) {
  return addresses.find(address => address.isPrimary) ?? addresses[0]
}

function normalizeCustomerRecord(customer: CustomerRecord): CustomerRecord {
  return {
    ...customer,
    displayName: customer.displayName || customer.legalCompanyName,
    customerNumber: customer.customerNumber ?? '',
    primaryContact: customer.primaryContact ?? '',
    primaryEmail: customer.primaryEmail ?? '',
    primaryPhone: customer.primaryPhone ?? '',
    website: customer.website ?? '',
    active: customer.active ?? true,
    useCount: Number(customer.useCount || 0),
    createdAt: customer.createdAt || new Date().toISOString(),
    updatedAt: customer.updatedAt || new Date().toISOString(),
    lastUsedAt: customer.lastUsedAt ?? '',
  }
}

function normalizeAddressRecord(address: CustomerAddressRecord): CustomerAddressRecord {
  return {
    ...address,
    label: address.label || address.type || 'Main Office',
    type: address.type || 'Main Office',
    contactName: address.contactName ?? '',
    streetAddress1: address.streetAddress1 ?? '',
    streetAddress2: address.streetAddress2 ?? '',
    city: address.city ?? '',
    state: address.state ?? '',
    zipCode: address.zipCode ?? '',
    country: address.country ?? '',
    email: address.email ?? '',
    phone: address.phone ?? '',
    isPrimary: address.isPrimary ?? false,
    active: address.active ?? true,
    useCount: Number(address.useCount || 0),
    createdAt: address.createdAt || new Date().toISOString(),
    updatedAt: address.updatedAt || new Date().toISOString(),
    lastUsedAt: address.lastUsedAt ?? '',
  }
}

async function saveCustomers(customers: CustomerRecord[]) {
  const normalized = customers.map(normalizeCustomerRecord)
  const saved = await replacePilotCollection('customers', normalized, loadCustomers())
  writeLocalCollection(CUSTOMER_STORAGE_KEY, saved)
  window.dispatchEvent(new Event('cronos:customers-changed'))
}

async function saveAddresses(addresses: CustomerAddressRecord[]) {
  const normalized = addresses.map(normalizeAddressRecord)
  const saved = await replacePilotCollection('customer-addresses', normalized, loadCustomerAddresses())
  writeLocalCollection(ADDRESS_STORAGE_KEY, saved)
  window.dispatchEvent(new Event('cronos:customers-changed'))
}

function reportPilotSyncError(error: unknown) {
  window.dispatchEvent(new CustomEvent('cronos:remote-sync-error', {
    detail: error instanceof Error ? error.message : 'Atlas data API sync failed.',
  }))
}

function normalizeSearch(value: string) {
  return String(value ?? '').toLowerCase().replace(/[.,#]/g, '').replace(/\s+/g, ' ').trim()
}

function normalizeCompany(value: string) {
  return normalizeSearch(value).replace(/\b(inc|llc|ltd|corp|corporation|company|co)\b/g, '').trim()
}

function normalizeAddress(value: string) {
  return normalizeSearch(value)
    .replace(/\bstreet\b/g, 'st')
    .replace(/\bst\.\b/g, 'st')
    .replace(/\bavenue\b/g, 'ave')
    .replace(/\bsuite\b/g, 'ste')
    .replace(/\bste\.\b/g, 'ste')
}

function normalizePhone(value: string) {
  return String(value ?? '').replace(/\D/g, '')
}

import { cachedProjects } from './projectCache'
import { readLocalCollection, writeLocalCollection } from './remoteRecords'
import seedCatalog from '../data/part-catalog-seed.json'
import type { Project, PurchaseOrder } from '../types'

const STORAGE_KEY = 'cronos.partCatalog'

export type PartPriceRecord = {
  id: string
  partNumber: string
  manufacturer: string
  description: string
  vendor: string
  unitCost: number
  quantityOrdered: number
  poNumber: string
  projectId: string
  projectNumber: string
  projectName: string
  quoteId?: string
  dateIssued: string
  recordedAt: string
}

export function loadPartCatalog() {
  const seedRecords = (seedCatalog as PartPriceRecord[]).map(normalizeRecord)

  try {
    return dedupeRecords([...cachedProjects().flatMap(project=>project.purchaseOrders.flatMap(po=>po.lines.map(line=>({id:po.poNumber+':'+line.id,partNumber:line.partNumber,manufacturer:line.manufacturer??'',description:line.description,vendor:po.vendor,unitCost:line.unitCost,quantityOrdered:line.quantityOrdered,poNumber:po.poNumber,projectId:project.id,projectNumber:project.projectNumber,projectName:project.projectName,quoteId:po.quoteId,dateIssued:po.dateIssued,recordedAt:project.updatedAt||project.createdAt||''})))), ...loadStoredPartCatalog(), ...seedRecords]).filter(record => record.partNumber)
  } catch {
    return seedRecords
  }
}

export function savePartCatalog(records: PartPriceRecord[]) {
  const normalized = dedupeRecords(records.map(normalizeRecord))
  writeLocalCollection(STORAGE_KEY, normalized)
  return normalized
}

export function recordPurchaseOrdersInCatalog(project: Project, purchaseOrders: PurchaseOrder[]) {
  const existing = loadStoredPartCatalog()
  const records = purchaseOrders.flatMap(po =>
    po.lines.map(line => ({
      id: `${po.poNumber}:${line.id}`,
      partNumber: line.partNumber.trim(),
      manufacturer: (line.manufacturer ?? '').trim(),
      description: line.description.trim(),
      vendor: po.vendor.trim(),
      unitCost: normalizeMoney(line.unitCost),
      quantityOrdered: line.quantityOrdered,
      poNumber: po.poNumber,
      projectId: project.id,
      projectNumber: project.projectNumber,
      projectName: project.projectName,
      quoteId: po.quoteId,
      dateIssued: po.dateIssued,
      recordedAt: new Date().toISOString(),
    })),
  )

  return savePartCatalog([...records, ...existing])
}

export function rebuildPartCatalogFromProjects(projects: Project[]) {
  const records = projects.flatMap(project =>
    project.purchaseOrders.flatMap(po =>
      po.lines.map(line => ({
        id: `${po.poNumber}:${line.id}`,
        partNumber: line.partNumber.trim(),
        manufacturer: (line.manufacturer ?? '').trim(),
        description: line.description.trim(),
        vendor: po.vendor.trim(),
        unitCost: normalizeMoney(line.unitCost),
        quantityOrdered: line.quantityOrdered,
        poNumber: po.poNumber,
        projectId: project.id,
        projectNumber: project.projectNumber,
        projectName: project.projectName,
        quoteId: po.quoteId,
        dateIssued: po.dateIssued,
        recordedAt: new Date().toISOString(),
      })),
    ),
  )

  return savePartCatalog([...records, ...loadStoredPartCatalog()])
}

export function findLatestPartPrice(partNumber: string) {
  const normalized = normalizePartNumber(partNumber)
  if (!normalized) return undefined

  return loadPartCatalog()
    .filter(record => normalizePartNumber(record.partNumber) === normalized)
    .sort((a, b) => new Date(b.dateIssued || b.recordedAt).getTime() - new Date(a.dateIssued || a.recordedAt).getTime())[0]
}

export function findPartPriceSuggestions(query: string, limit = 8) {
  const normalized = normalizePartNumber(query)
  if (!normalized || normalized.length < 2) return []

  return getPartCatalogSummary(loadPartCatalog())
    .filter(record => {
      const searchable = [record.partNumber, record.manufacturer, record.description, record.vendor].join(' ')
      return normalizePartNumber(searchable).includes(normalized)
    })
    .slice(0, limit)
}

export function getPartCatalogSummary(records: PartPriceRecord[]) {
  const latestByPart = new Map<string, PartPriceRecord>()

  records
    .slice()
    .sort((a, b) => new Date(b.dateIssued || b.recordedAt).getTime() - new Date(a.dateIssued || a.recordedAt).getTime())
    .forEach(record => {
      const key = normalizePartNumber(record.partNumber)
      if (key && !latestByPart.has(key)) latestByPart.set(key, record)
    })

  return Array.from(latestByPart.values())
}

function dedupeRecords(records: PartPriceRecord[]) {
  const seen = new Set<string>()
  return records.filter(record => {
    const key = record.id || `${record.poNumber}:${record.partNumber}`
    if (seen.has(key)) return false
    seen.add(key)
    return true
  })
}

function loadStoredPartCatalog() {
  try {
    return (JSON.parse(window.localStorage.getItem(STORAGE_KEY) ?? '[]') as PartPriceRecord[]).map(normalizeRecord)
  } catch {
    return []
  }
}

function normalizeRecord(record: PartPriceRecord): PartPriceRecord {
  return {
    ...record,
    partNumber: record.partNumber ?? '',
    manufacturer: record.manufacturer ?? '',
    description: record.description ?? '',
    vendor: record.vendor ?? '',
    unitCost: normalizeMoney(record.unitCost),
    quantityOrdered: Number.isFinite(record.quantityOrdered) ? record.quantityOrdered : 0,
    recordedAt: record.recordedAt ?? record.dateIssued ?? new Date().toISOString(),
  }
}

function normalizePartNumber(value: string) {
  return value.trim().toLowerCase()
}

function normalizeMoney(value: number) {
  return Number.isFinite(value) ? Math.max(0, Math.round((value + Number.EPSILON) * 100) / 100) : 0
}

