export type ActionStatus = 'Open'|'In Progress'|'Complete'|'Cancelled'
export type ProcurementNote={id:string;projectId:string;text:string;createdBy:string;createdByName:string;createdAt:string;meetingDate?:string;type:'Weekly Sync'|'General'}
export type ProcurementAction={id:string;projectId:string;description:string;ownerId:string;ownerName:string;assignedBy:string;assignedByName:string;assignedAt:string;dueDate:string;status:ActionStatus;completedAt?:string;priority:'Low'|'Medium'|'High'|'Critical';comment?:string;meetingDate?:string}
export type DiscussionFlag={id:string;projectId:string;reason:string;flaggedBy:string;flaggedByName:string;flaggedAt:string;resolvedAt?:string;resolvedBy?:string}
export type ProcurementOverride={projectId:string;phase?:ProcurementPhase;phaseEnteredAt?:string;health?:ProcurementHealth;reason?:string;updatedBy:string;updatedAt:string}
