export function identifyLegacyDirectoryRecords(collection, records) {
  // Keep the first ID so existing project/address references remain valid.
  // Each additional entry keeps its complete payload under a stable UUID. The
  // frozen source array is never rewritten; its position supplies provenance.
  const reserved = new Set(records.map(record => record?.id).filter(Boolean))
  const seen = new Set()
  return records.map((record, index) => {
    if (!record || typeof record !== 'object' || Array.isArray(record)) {
      throw new DataValidationError(`The legacy ${collection} entry ${index + 1} is invalid.`, 409)
    }
    const sourceId = record.id
    let id = sourceId
    if (!id || seen.has(id)) {
      let attempt = 0
      do {
        const hex = createHash('sha256').update(JSON.stringify(['atlas-legacy-directory-v1', collection, index, sourceId ?? null, attempt++])).digest('hex')
        id = `${hex.slice(0,8)}-${hex.slice(8,12)}-8${hex.slice(13,16)}-a${hex.slice(17,20)}-${hex.slice(20,32)}`
      } while (reserved.has(id) || seen.has(id))
      seen.add(id)
      return { ...record, id, legacyDirectorySourceId: sourceId ?? null, legacyDirectoryRecordIndex: index, version: 0 }
    }
    seen.add(id)
    return { ...record, version: 0 }
  })
}
