    if (!Array.isArray(data)) throw new Error('The database did not confirm the directory save.')
    const confirmed = await this.listCollection(collection)
    return { records: confirmed, count: confirmed.length }
  }
  async reconcile(collection) {
    const table = TABLES[collection]
    if (!table) throw new Error('Unsupported collection')
    const { data, error } = await this.client.from(table).select('*').is('deleted_at', null)
    if (error) throw error
    const rows = data || []
    const keys = new Map()
    for (const row of rows) {
      const key = collection === 'customers' ? row.customer_number : collection === 'vendors' ? row.vendor_number : null
      if (key) keys.set(key, (keys.get(key) || 0) + 1)
    }
    return {
      collection, recordCount: rows.length, missingIds: rows.filter(row => !row.id).length,
      duplicateBusinessKeys: [...keys].filter(([, count]) => count > 1).map(([key, count]) => ({ key, count })),
      orphanedRelationships: collection === 'customer-addresses' ? await this.countOrphanAddresses() : 0,
      financialTotal: null, missingDocumentReferences: null,
    }
  }
  async countOrphanAddresses() {
    const { data, error } = await this.client.from('atlas_customer_addresses').select('customer_id,atlas_customers!left(id)').is('deleted_at', null)
    if (error) throw error
    return (data || []).filter(row => !row.atlas_customers).length
  }
  async exportCollection(collection) {
    const result = []
    for(let offset=0;;offset+=500) {
      const {data,error}=await this.client.from(TABLES[collection]).select('*').order('created_at').order('id').range(offset,offset+499)
      if(error)throw error
      result.push(...(data||[]));if(!data || data.length<500)return result
    }
  }
}
function base(record, actorId) {
  const now = new Date().toISOString()
  return {
    id: record.id || record.vendorId, source_system: 'atlas_legacy', source_id: record.vendorId || record.id,
    created_at: record.createdAt || record.createdDate || now, created_by: actorId,
    updated_at: now, updated_by: actorId, version: Number(record.version || 1), deleted_at: null, deleted_by: null,
  }
}
function mapRecord(collection, record, actorId) {
  const common = base(record, actorId)
  if (collection === 'customers') return {
    ...common, legacy_payload: record, customer_number: record.customerNumber || null, legal_name: record.legalCompanyName,
    display_name: record.displayName, primary_contact_name: record.primaryContact || null,
    primary_email: record.primaryEmail || null, primary_phone: record.primaryPhone || null,
    website: record.website || null, status: record.active === false ? 'inactive' : 'active',
  }
  if (collection === 'customer-addresses') return {
    ...common, legacy_payload: record, customer_id: record.customerId, label: record.label, address_type: snake(record.type),
    contact_name: record.contactName || null, address_line_1: record.streetAddress1 || null,
    address_line_2: record.streetAddress2 || null, city: record.city || null, state_province: record.state || null,
    postal_code: record.zipCode || null, country_code: addressCountryCode(record), email: record.email || null,
    phone: record.phone || null, is_primary: Boolean(record.isPrimary), status: record.active === false ? 'inactive' : 'active',
  }
  return {
    ...common, vendor_number: record.vendorId, legal_name: record.vendor, dba_name: record.dbaName || null,
    website: record.website || null, status: record.status === 'Inactive' ? 'inactive' : 'active',
    is_preferred: Boolean(record.preferredVendor || record.status === 'Preferred'), cage_code: record.cageCode || null,
    uei: record.uei || null, duns: record.duns || null, tax_id: record.taxId || null,
    payment_terms: record.paymentTerms || null, account_number: record.accountNumber || null,
    notes: record.notes || null, legacy_payload: record,
  }
}
function addressCountryCode(record) {
  try { return normalizeCountryCode(record.country) }
  catch {
    const label = String(record.label || record.streetAddress1 || record.id || 'selected address').slice(0, 100)
    throw new DataValidationError('Country for customer address "' + label + '" is not recognized. Use a country name or two-letter code, such as United States or US.', 400, {field: 'country', addressId: record.id})
  }
}
function snake(value) { return String(value || 'other').trim().toLowerCase().replace(/\s+/g, '_') }
export class DataValidationError extends Error {
  constructor(message, status = 400, details = {}) {
    super(message)
    this.status = status
    this.details = details
  }
}

export function fromRow(collection, r) {
  const common = { ...r.legacy_payload, id: r.id, version: Number(r.version), createdAt: r.created_at, updatedAt: r.updated_at }
  if (collection === 'customers') return { ...common, customerNumber: r.customer_number || '', legalCompanyName: r.legal_name, displayName: r.display_name, primaryContact: r.primary_contact_name || '', primaryEmail: r.primary_email || '', primaryPhone: r.primary_phone || '', website: r.website || '', active: r.status === 'active', useCount: common.useCount || 0, lastUsedAt: common.lastUsedAt || '' }
  if (collection === 'customer-addresses') return { ...common, customerId: r.customer_id, label: r.label, type: r.address_type.split('_').map(w => w[0].toUpperCase()+w.slice(1)).join(' '), contactName: r.contact_name || '', streetAddress1: r.address_line_1 || '', streetAddress2: r.address_line_2 || '', city: r.city || '', state: r.state_province || '', zipCode: r.postal_code || '', country: r.country_code || '', email: r.email || '', phone: r.phone || '', isPrimary: r.is_primary, active: r.status === 'active', useCount: common.useCount || 0, lastUsedAt: common.lastUsedAt || '' }
  return { ...common, vendorId: r.vendor_number, vendor: r.legal_name, dbaName: r.dba_name || '', website: r.website || '', status: r.status === 'inactive' ? 'Inactive' : r.is_preferred ? 'Preferred' : 'Active', preferredVendor: r.is_preferred, cageCode: r.cage_code || '', uei: r.uei || '', duns: r.duns || '', taxId: r.tax_id || '', paymentTerms: r.payment_terms || '', accountNumber: r.account_number || '', notes: r.notes || '', createdDate: r.created_at, lastUpdated: r.updated_at }
}

