  from(table){
   if(!['app_records','atlas_customers','atlas_customer_addresses','atlas_vendors'].includes(table))throw Error('Unexpected test table')
   let op='read',body,filters=[],single=false,range
   const q={select(){return q},order(){return q},eq(key,value){filters.push([key,'=',value]);return q},is(key,value){filters.push([key,'is',value]);return q},range(a,b){range=[a,b];return q},update(value){op='update';body=value;return q},insert(value){op='insert';body=value;return q},maybeSingle(){single=true;return q},single(){single=true;return q},then(resolve,reject){return run().then(resolve,reject)}}
   async function run(){try{
