-- Install after 20260916_project_records_and_approval_protection.sql.
-- This migration is transactional and keeps the existing directory tables.
begin;
alter table public.atlas_customers add column if not exists legacy_payload jsonb not null default '{}'::jsonb;
alter table public.atlas_customer_addresses add column if not exists legacy_payload jsonb not null default '{}'::jsonb;

create or replace function public.atlas_apply_directory_changes(p_collection text, p_changes jsonb, p_actor uuid)
returns jsonb language plpgsql security definer set search_path = public, pg_temp as $$
declare
  tbl text; change jsonb; current_row jsonb; next_row jsonb; result jsonb;
  column_names text; column_values text; update_columns text;
begin
  tbl := case p_collection when 'customers' then 'atlas_customers' when 'customer-addresses' then 'atlas_customer_addresses' when 'vendors' then 'atlas_vendors' end;
  if tbl is null or jsonb_typeof(p_changes) <> 'array' or p_actor is null then raise exception 'Invalid directory save'; end if;
  perform pg_advisory_xact_lock(hashtext('atlas_directory:' || tbl));
  for change in select value from jsonb_array_elements(p_changes) loop
    execute format('select to_jsonb(t) from public.%I t where id=$1 for update',tbl) into current_row using (change->>'id')::uuid;
    if current_row is null then
      if change->>'expected_version' is not null then raise exception 'This record was removed. Reload the directory.' using errcode='40001'; end if;
    elsif current_row->>'deleted_at' is not null or change->>'expected_version' is null or (current_row->>'version')::bigint <> (change->>'expected_version')::bigint then
      raise exception 'This directory record changed while you were editing. Reload and review the latest version.' using errcode='40001';
    end if;
    if change->'data' = 'null'::jsonb then
      if current_row is null then raise exception 'Record to delete was not found'; end if;
      execute format('update public.%I set deleted_at=clock_timestamp(),deleted_by=$2,updated_by=$2,updated_at=clock_timestamp(),version=version+1 where id=$1',tbl) using (change->>'id')::uuid,p_actor;
      next_row := null;
    else
      if change->'data'->>'id' <> change->>'id' then raise exception 'Record ID mismatch'; end if;
      next_row := change->'data' || jsonb_build_object('id',change->>'id','version',coalesce((current_row->>'version')::bigint,0)+1,'updated_at',clock_timestamp(),'updated_by',p_actor,'created_at',coalesce(current_row->'created_at',to_jsonb(clock_timestamp())),'created_by',coalesce(current_row->'created_by',to_jsonb(p_actor)),'deleted_at',null,'deleted_by',null);
      select string_agg(quote_ident(column_name),',' order by ordinal_position), string_agg('r.'||quote_ident(column_name),',' order by ordinal_position), string_agg(quote_ident(column_name)||'=excluded.'||quote_ident(column_name),',' order by ordinal_position) filter(where column_name <> 'id')
        into column_names,column_values,update_columns from information_schema.columns where table_schema='public' and table_name=tbl;
      execute format('insert into public.%I (%s) select %s from jsonb_populate_record(null::public.%I,$1) r on conflict(id) do update set %s',tbl,column_names,column_values,tbl,update_columns) using next_row;
    end if;
    insert into public.atlas_data_audit_events(entity_type,entity_id,action,actor_id,previous_value,new_value)
      values(p_collection,(change->>'id')::uuid,case when next_row is null then 'deleted' when current_row is null then 'created' else 'updated' end,p_actor,current_row,next_row);
  end loop;
  execute format('select coalesce(jsonb_agg(to_jsonb(t) order by created_at,id),''[]''::jsonb) from public.%I t where deleted_at is null',tbl) into result;
  return result;
end $$;
revoke all on function public.atlas_apply_directory_changes(text,jsonb,uuid) from public,anon,authenticated;
grant execute on function public.atlas_apply_directory_changes(text,jsonb,uuid) to service_role;

-- Monotonic revisions make generic collection updates safe even within the same millisecond.
alter table public.app_records add column if not exists revision bigint not null default 1;
create or replace function public.atlas_guard_collection_revision() returns trigger
language plpgsql set search_path=public,pg_temp as $$
begin
  if old.record_type in ('customers','customer_addresses') and new.data is distinct from old.data then
    raise exception 'Reload Atlas: directory updates now use the confirmed directory API.' using errcode='40001';
  end if;
  if old.record_type in ('customer_orders','weekly_procurement','procurement_tasks','vendor_import_logs') and new.data is distinct from old.data then
    if new.revision <> old.revision + 1 then raise exception 'Reload Atlas before saving: this collection requires a confirmed revision.' using errcode='40001'; end if;
    new.updated_at := clock_timestamp();
  end if;
  return new;
end $$;
drop trigger if exists atlas_guard_collection_revision on public.app_records;
create trigger atlas_guard_collection_revision before update on public.app_records for each row execute function public.atlas_guard_collection_revision();
commit;

// Shared SpreadsheetML/Open Packaging structure for every Atlas XLSX writer.
// https://learn.microsoft.com/en-us/dotnet/api/documentformat.openxml.spreadsheet.pane
export const WORKBOOK_VIEWS_XML = '<bookViews><workbookView/></bookViews>'

/** Counts are explicit: a column offset is emitted only when columns are frozen. */
export function sheetViewsXml(freeze) {
  if (freeze === undefined) return ''
  if (!freeze || typeof freeze !== 'object' || Array.isArray(freeze) || Object.keys(freeze).some(key => !['rows', 'columns'].includes(key))) {
    throw new Error('Freeze panes require explicit rows and/or columns.')
  }
  const rows = freeze.rows ?? 0
  const columns = freeze.columns ?? 0
  if (!Number.isInteger(rows) || rows < 0 || rows >= 1048576 || !Number.isInteger(columns) || columns < 0 || columns >= 16384) {
    throw new Error('Frozen row/column counts must be nonnegative integers within Excel worksheet limits.')
  }
  if (!rows && !columns) return ''
  let column = '', index = columns + 1
  while (index) {
    column = String.fromCharCode(65 + (index - 1) % 26) + column
    index = Math.floor((index - 1) / 26)
  }
  const topLeftCell = column + (rows + 1)
  const activePane = columns ? (rows ? 'bottomRight' : 'topRight') : 'bottomLeft'
  const selection = (pane, cell) => `<selection pane="${pane}" activeCell="${cell}" sqref="${cell}"/>`
  const selections = columns && rows
    ? selection('topRight', column + '1') + selection('bottomLeft', 'A' + (rows + 1)) + selection('bottomRight', topLeftCell)
    : selection(activePane, topLeftCell)
  const splits = (columns ? ' xSplit="' + columns + '"' : '') + (rows ? ' ySplit="' + rows + '"' : '')
  return `<sheetViews><sheetView workbookViewId="0"><pane${splits} topLeftCell="${topLeftCell}" activePane="${activePane}" state="frozen"/>${selections}</sheetView></sheetViews>`
}

/** OPC dates require an explicit W3CDTF type; Excel rejects the package without it. */
export function corePropertiesXml(creator, createdAt = new Date().toISOString()) {
  const escape = value => String(value).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;').replace(/'/g, '&apos;')
  return `<cp:coreProperties xmlns:cp="http://schemas.openxmlformats.org/package/2006/metadata/core-properties" xmlns:dc="http://purl.org/dc/elements/1.1/" xmlns:dcterms="http://purl.org/dc/terms/" xmlns:xsi="http://www.w3.org/2001/XMLSchema-instance"><dc:creator>${escape(creator)}</dc:creator><dcterms:created xsi:type="dcterms:W3CDTF">${escape(createdAt)}</dcterms:created></cp:coreProperties>`
}

