const names = new Map()
const labels = new Intl.DisplayNames(['en'], {type: 'region', fallback: 'none'})
const key = value => value.normalize('NFKD').replace(/[\u0300-\u036f]/g, '').toLowerCase().replace(/[^a-z0-9]/g, '')
for (const code of regions) {
  const name = labels.of(code)
  if (name) names.set(key(name), code)
}
for (const [name, code] of [
  ['United States of America', 'US'], ['U.S.', 'US'], ['U.S.A.', 'US'],
  ['UK', 'GB'], ['U.K.', 'GB'], ['Great Britain', 'GB'],
  ['United Kingdom of Great Britain and Northern Ireland', 'GB'],
  ['Republic of Korea', 'KR'], ['South Korea', 'KR'], ['North Korea', 'KP'],
  ['Viet Nam', 'VN'], ['Russian Federation', 'RU'],
]) names.set(key(name), code)

export function normalizeCountryCode(value) {
  const text = String(value ?? '').trim()
  // Retain the existing default for addresses that omit a country.
  if (!text) return 'US'
  const upper = text.toUpperCase()
  const code = names.get(key(text)) || (regions.has(upper) ? upper : alpha3.get(upper))
  if (code) return code
  throw new Error('Enter a recognized country name or two-letter country code, such as United States or US.')
}

import test from 'node:test'
import assert from 'node:assert/strict'
import {randomUUID} from 'node:crypto'
import {businessDatabase,databaseClient,actor} from './fixtures/business-saves-database.mjs'
import {SupabasePilotRepository} from '../data-repositories.mjs'

test('saving a linked legacy address converts its full country name even when the project already says US',async()=>{
 const db=await businessDatabase();try{
  const repo=new SupabasePilotRepository(databaseClient(db)),customerId=randomUUID(),addressId=randomUUID()
  await repo.replaceCollection('customers',[{id:customerId,legalCompanyName:'Country regression customer',displayName:'Country regression customer',active:true}],actor,[])
  const original=[{id:addressId,customerId,label:'Project Site',type:'Project Site',streetAddress1:'1915 Test Road',city:'Shaw',state:'SC',zipCode:'29152',country:'United States',active:true,useCount:1}]
  await db.query("insert into app_records(record_type,record_key,data) values('customer_addresses','all',$1)",[JSON.stringify(original)])
  const before=await repo.listCollection('customer-addresses')
  const confirmed=await repo.replaceCollection('customer-addresses',before.map(r=>({...r,useCount:r.useCount+1})),actor,before)
  assert.equal(confirmed.records[0].country,'US');assert.equal(confirmed.records[0].version,1)
  const row=(await db.query('select country_code,legacy_payload from atlas_customer_addresses where id=$1',[addressId])).rows[0]
  assert.equal(row.country_code,'US');assert.equal(row.legacy_payload.country,'United States')
  assert.deepEqual((await db.query("select data from app_records where record_type='customer_addresses'")).rows[0].data,original)
 }finally{await db.close()}
})

test('country names and abbreviations are converted before insertion; invalid input writes no partial batch',async()=>{
 const db=await businessDatabase();try{
  const repo=new SupabasePilotRepository(databaseClient(db)),customerId=randomUUID()
  await repo.replaceCollection('customers',[{id:customerId,legalCompanyName:'International customer',displayName:'International customer',active:true}],actor,[])
  const inputs=[['United States','US'],[' USA ','US'],['U.S.A.','US'],['United States of America','US'],[' us ','US'],['Canada','CA'],['CAN','CA'],['United Kingdom','GB'],['UK','GB'],['GBR','GB'],['Germany','DE'],['France','FR'],['United Arab Emirates','AE'],['South Korea','KR'],['','US']]
  const addresses=inputs.map(([country],index)=>({id:randomUUID(),customerId,label:'Address '+index,type:'Shipping',country,streetAddress1:'Address '+index,active:true}))
  const confirmed=await repo.replaceCollection('customer-addresses',addresses,actor,[])
  for(let i=0;i<inputs.length;i++)assert.equal(confirmed.records.find(r=>r.id===addresses[i].id).country,inputs[i][1])
  const invalid=[{...addresses[0],id:randomUUID(),country:'Australia'},{...addresses[0],id:randomUUID(),label:'Invalid country example',country:'United Something Invalid'}]
  await assert.rejects(repo.replaceCollection('customer-addresses',invalid,actor,[]),error=>error.status===400 && /Country.*Invalid country example.*not recognized/.test(error.message))
  assert.equal((await repo.listCollection('customer-addresses')).length,addresses.length)
  const original=confirmed.records[0]
  await repo.replaceCollection('customer-addresses',[{...original,country:'Canada'}],actor,[original])
  await assert.rejects(repo.replaceCollection('customer-addresses',[{...original,country:'France'}],actor,[original]),/changed while/)
  assert.equal((await repo.listCollection('customer-addresses')).find(r=>r.id===original.id).country,'CA')
 }finally{await db.close()}
})
